<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { longMonitorApi } from '@/api/longMonitor'
import { useAuthStore } from '@/stores/auth'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),row=ref<any>({}),history=ref<any[]>([]),loading=ref(false),id=Number(route.params.id),data=(r:any)=>r.data.data
async function load(){loading.value=true;try{const d=data(await longMonitorApi.monitor(id))||{};row.value=d;history.value=d.checkHistory||d.check_history||[]}finally{loading.value=false}}onMounted(load)
</script><template><div class="page"><div class="head"><div><h2>长效监控详情</h2><p>查看客户、长效服务、代理目标、机器人以及检测状态。</p></div><el-button @click="router.back()">返回</el-button></div><el-card shadow="never" v-loading="loading"><el-descriptions :column="3" border><el-descriptions-item label="监控编号">{{row.monitor_no}}</el-descriptions-item><el-descriptions-item label="客户"><el-button v-if="auth.hasPermission('customer:read')" link type="primary" @click="router.push('/customers/'+row.customer_id)">{{row.customer_name}}</el-button><span v-else>{{row.customer_name}}</span></el-descriptions-item><el-descriptions-item label="服务"><el-button v-if="auth.hasPermission('service:read')" link type="primary" @click="router.push('/services/'+row.service_id)">{{row.service_no}}</el-button><span v-else>{{row.service_no}}</span></el-descriptions-item><el-descriptions-item label="目标">{{row.target_host}}:{{row.target_port}}</el-descriptions-item><el-descriptions-item label="协议">{{row.proxy_protocol}}</el-descriptions-item><el-descriptions-item label="检测方式">{{row.check_method}}</el-descriptions-item><el-descriptions-item label="检测周期">{{row.interval_seconds}} 秒</el-descriptions-item><el-descriptions-item label="失败阈值">{{row.failure_threshold}}</el-descriptions-item><el-descriptions-item label="恢复阈值">{{row.recovery_threshold}}</el-descriptions-item><el-descriptions-item label="当前状态">{{row.current_status}}</el-descriptions-item><el-descriptions-item label="机器人"><el-button v-if="row.bot_id&&auth.hasPermission('long-monitor:bot:read')" link type="primary" @click="router.push('/long-monitor/bots/'+row.bot_id)">{{row.bot_name}}</el-button><span v-else>{{row.bot_name||'未设置'}}</span></el-descriptions-item><el-descriptions-item label="最近检测">{{row.last_checked_at||'尚无真实探测结果'}}</el-descriptions-item><el-descriptions-item label="最近错误">{{row.last_error||'—'}}</el-descriptions-item></el-descriptions></el-card><el-card shadow="never"><template #header><div style="display:flex;justify-content:space-between;align-items:center"><b>检测历史</b><el-button v-if="auth.hasPermission('long-monitor:notification:read')" link type="primary" @click="router.push({path:'/long-monitor/notifications',query:{customerId:String(row.customer_id),monitorId:String(id)}})">查看该监控通知</el-button></div></template><el-alert type="info" :closable="false" title="管理面记录不等于真实网络恢复；没有检测记录表示尚无可用的探测证据。"/><el-table :data="history"><el-table-column prop="checked_at" label="检测时间" width="190"/><el-table-column prop="success" label="成功"/><el-table-column prop="latency_ms" label="延迟(ms)"/><el-table-column prop="outbound_ip" label="出口IP"/><el-table-column prop="response_code" label="响应码"/><el-table-column prop="error_message" label="错误" min-width="180"/></el-table></el-card></div></template><style scoped>.page{display:grid;gap:16px}.head{display:flex;justify-content:space-between}.head h2{margin:0 0 6px}.head p{margin:0;color:#7b8494}</style>